head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gParamObj;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vScrenID = 'ULDSTF30001.xml';
scwin.gMarket = js_market; //시장구분
scwin.strDepCd = js_dep_cd.substring(0, 2);
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Init = function() {
    dts_Status.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=C&CD_ENG_NM=DISCLS_SCHDL_ACT_STAT_CD";
    dts_Status.Reset();
    $c.stf.setObjectValue(rdo_Market_Flag, scwin.gLdMktTp);
    //코스닥만 SMS 기능 보이게
    $c.stf.showObj(label_3, false);
    $c.stf.showObj(cmb_SMS, false);

    //코스닥 시장운영팀은 '확인여부'가 불필요하다.
    if (scwin.gDepCd == '3220') {
        $c.stf.showObj(label_1, false);
        $c.stf.showObj(cmb_Confirm, false);
    } else if (js_market == "1") {
        //유가시장은 안보여야 함
        label_1.style.display = "none"; //담당자확인여부
        cmb_Confirm.style.display = "none"; //담당자확인여부

    } else if (js_market == "2") {
        $c.stf.showObj(label_3, true);
        $c.stf.showObj(cmb_SMS, true);
    } else if (js_market == "3") {
        //파생은 안보여야 함_LSH
        label_1.style.display = "none"; //담당자확인여부
        cmb_Confirm.style.display = "none"; //담당자확인여부

    }
    if (scwin.gDepCd == "11D0") {
        $c.stf.showObj(label_12, false);
        $c.stf.showObj(label_digital, true);
        $c.stf.showObj(panel_chrg, false);
    } else {
        $c.stf.showObj(label_12, true);
        $c.stf.showObj(label_digital, false);
        $c.stf.showObj(panel_chrg, true);
    }
    //2014.02.09 유가 공시서비스팀 추가
    //2650 추가 2021.02.22
    //2660 추가 2021.03.12
    //strDepCd 로 변경 2021.05.28
    //if((js_dep_cd == '2620' || js_dep_cd == '2630' || js_dep_cd == '2611' || js_dep_cd == '2650' || js_dep_cd == '2660')) { 
    if (scwin.strDepCd == '26') {
        $c.stf.showObj(txb_DISCLS_SCHDL_GRD_CD, true); //등급
        $c.stf.showObj(label_2, true);
    } else {
        $c.stf.showObj(txb_DISCLS_SCHDL_GRD_CD, false); //등급
        $c.stf.showObj(label_2, false); //등급

    }

    //showObj(panel_chrg, false);

};
scwin.fn_HideDebugCtrls = function() {
    // 키값으로 사용하지만 화면상에 표시될 필요가 없는 것들
    $c.stf.showObj(panel_hidden_values, false);
    $c.stf.showObj(panel_key_values, false);
    $c.stf.showObj(btn_Delete, false);
    if (js_market == "3") {
        //파생은 안보여야 함_LSH
        $c.stf.showObj(btn_Multi, false);
    }
};
scwin.fn_MoveWin = function() {
    $c.stf.MoveCenterOfParent();
};
scwin.fn_resizeToWin = function() {
    frame.Width = 500;
    frame.Height = 560;
};
scwin.fn_ReadChrgInfo = function(vISUR_CD, vLD_MKT_TP_CD) {
    // 공시담당자1, 공시담당자(유, 코)
    url = "/ListedCompany.do?method=readChargeIssue&Flag=4&ISUR_CD=" + vISUR_CD + "&MKT_TP_CD=" + vLD_MKT_TP_CD;
    dts_Charge2_Info.DataID = encodeURI(url);
    dts_Charge2_Info.Reset();
};
scwin.fn_ReadChrgInfo2 = function() {
    var vISUR_CD = MxDataSet_com_isur.getCellData(MxDataSet_com_isur.getRowPosition(), "ISUR_CD");
    var vLD_MKT_TP_CD = MxDataSet_com_isur.getCellData(MxDataSet_com_isur.getRowPosition(), "SPOT_ISU_TRD_MKT_TP_CD");
    if (vISUR_CD != '' && vISUR_CD.length == 5) {
        scwin.fn_ReadChrgInfo(vISUR_CD, vLD_MKT_TP_CD);
    }
};
scwin.afterExec = function(isur_cd, ld_mkt_tp_cd) {
    if (isur_cd != '' && ISUR_CD.length == 5) {
        scwin.fn_ReadChrgInfo(isur_cd, ld_mkt_tp_cd);
    }
};
scwin.fn_readSchedule = function() {
    var url = "/DisclosureSchedule.do?method=readSchedule";
    url += "&DISCLS_SCHDL_ADM_DD=" + $c.stf.getObjectValue(txb_DISCLS_SCHDL_ADM_DD);
    url += "&BYDD_SEQ=" + $c.stf.getObjectValue(txb_BYDD_SEQ);
    url += "&INTEG_USR_ID=" + $c.stf.getObjectValue(txb_INTEG_USR_ID); // 통합사용자ID
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Schedule.DataID = encodeURI(url);
    dts_Schedule.Reset();

    //2009.08.07 담당자확인여부추가
    if (js_market == "2" || js_market == "6") {
        // 코넥스 시장 추가
        $c.stf.setObjectValue(cmb_Confirm, dts_Schedule.getCellData(1, "SCHDL_CONFRM_YN"));
    }
    if (js_market == "2") {
        $c.stf.setObjectValue(cmb_SMS, dts_Schedule.getCellData(1, "SMS_TRNSM_YN"));
    }

    //setObjectValue(cmb_Status, dts_Schedule.NameString(1, "discls_schdl_act_stat_cd"));		

};
scwin.fn_openDiscls = async function() {
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("[회사]를 선택하세요");
        txb_ISUR_CD.focus();
        return;
    }
    var vISUR_CD = $c.stf.getObjectValue(txb_ISUR_CD);
    await $c.frame.CreateDialogFrame("wndDiscls|ISUR_CD=" + vISUR_CD, "/dsclmgt/ULDSTF30005.gfm", "공시선택", 10, 10, 10, 20, "window");
};
scwin.fn_Adm_Itm_Tp_Cd = async function() {
    await $c.frame.CreateDialogFrame("Adm_Itm", "/dsclmgt/ULDSTF30002.gfm", "관리항목유형", 10, 10, 10, 20, "window");
};
scwin.fn_getParam = function() {
    // opener로 부터 param을 받는다.
    var parentWin = $c.frame.path("../");
    //alert(frame.srcUrl);
    var src = $c.stf.getQuery(frame.srcUrl, "src");
    if (src == "JSP") // JSP call

    {
        var cmd = $c.stf.getQuery(frame.srcUrl, "cmd");
        if (cmd == "C") {
            scwin.fn_setNewMode();
        } else {
            var vDiscls_schdl_adm_dd = $c.stf.getQuery(frame.srcUrl, "discls_schdl_adm_dd");
            var vBydd_seq = $c.stf.getQuery(frame.srcUrl, "bydd_seq");
            var vInteg_usr_id = $c.stf.getQuery(frame.srcUrl, "integ_usr_id");
            $c.stf.setObjectValue(txb_Cmd, cmd);
            $c.stf.setObjectValue(txb_DISCLS_SCHDL_ADM_DD, vDiscls_schdl_adm_dd);
            $c.stf.setObjectValue(txb_BYDD_SEQ, vBydd_seq);
            $c.stf.setObjectValue(txb_INTEG_USR_ID, vInteg_usr_id);
            $c.stf.showObj(btn_VIEWDSCL, true);
            scwin.fn_readSchedule();
            $c.stf.showObj(btn_ISUR_CD, false);
            $c.stf.showObj(btn_Delete, true);
            txb_ISUR_CD.setReadOnly(true);
        }
    } else {
        var paramObj = parentWin.scwin.gParamObj;
        $c.stf.setObjectValue(txb_Cmd, paramObj.param0);
        $c.stf.setObjectValue(txb_DISCLS_SCHDL_ADM_DD, paramObj.param1);
        $c.stf.setObjectValue(txb_BYDD_SEQ, paramObj.param2);
        $c.stf.setObjectValue(txb_INTEG_USR_ID, paramObj.param3);
        //alert(paramObj.param0);
        if (paramObj.param0 == null || paramObj.param0 == undefined || paramObj.param0 == "" || paramObj.param0 == "C") {
            scwin.fn_setNewMode();
            $c.stf.showObj(btn_VIEWDSCL, false);
        } else if (paramObj.param0 == "R") {
            scwin.fn_readSchedule();
            $c.stf.showObj(btn_ISUR_CD, false);
            $c.stf.showObj(btn_Delete, true);
            txb_ISUR_CD.setReadOnly(true);
        }
    }
    //	var paramObj = parentWin.gParamObj;

    //	if (paramObj == undefined) return;

};
scwin.fn_setParam = function() {
    // child에 param을 넘긴다.
    var argv = fn_setParam.arguments;
    var argc = fn_setParam.arguments.length;
    scwin.gParamObj = new Array(argc); // 초기화
    for (var i = 0; i < argc; i++) // actual arguments

    {
        eval("gParamObj.param" + i + " = argv[" + i + "]");
    }
    return true;
};
scwin.fn_setNewMode = function() {
    // row 추가.
    // 헤더 꼭 가져와야되나.씨~~~
    dts_Schedule.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=SCHEDULE_INSERT_IN";
    dts_Schedule.Reset();
    dts_Schedule.insertRow();
    $c.stf.setObjectValue(txb_Cmd, "C");
    $c.stf.setObjectValue(txb_EMP_NO, js_emp_no);
    $c.stf.setObjectValue(rdo_Market_Flag, scwin.gLdMktTp);
};
scwin.fn_CheckForm = function() {
    // alert(getObjectValue(rdo_Market_Flag)); ??
    if ($c.stf.getObjectValue(rdo_Market_Flag) == "") {
        $c.win.alert("[시장구분]을 선택하세요.");
        rdo_Market_Flag.focus();
        return false;
    }
    /*
	if (getObjectValue(txb_ISUR_CD) == "")
	{
		alert("[회사코드]을 선택하세요.");txb_ISUR_CD.focus();return false;
	}	
   */
    if (js_sndloc == '13' && $c.stf.getObjectValue(txb_COM_NM) == "") {
        $c.win.alert("[회사코드]을 선택하세요.");
        txb_COM_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_Deadline) == "") {
        $c.win.alert("[관리기한]을 선택하세요.");
        edt_Deadline.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_SCHDL_ADM_ITM_TP_NM) == "") {
        $c.win.alert("[관리항목]을 선택하세요.");
        txb_SCHDL_ADM_ITM_TP_NM.focus();
        return false;
    }
    /*
    if (getObjectValue(txb_DISCLS_SCHDL_ADM_CONTN) == "")
    {
    	alert("[관리항목]을 선택하세요.");txb_DISCLS_SCHDL_ADM_CONTN.focus();return false;
    }
    if (getObjectValue(txb_ACPT_NO) == "")
    {
    	alert("[일정추출공시]을 선택하세요.");txb_ACPT_NO.focus();return false;
    }	
    if (getObjectValue(txb_RptNm) == "")
    {
    	alert("[일정추출공시]을 선택하세요.");txb_RptNm.focus();return false;
    }	
    if (getObjectValue(edt_DISCLS_PUBL_DDTM) == "")
    {
    	alert("[공시일]을 선택하세요.");edt_DISCLS_PUBL_DDTM.focus();return false;
    }	
    */
    if ($c.stf.getObjectValue(cmb_Status) == "") {
        $c.win.alert("[일정상태]을 선택하세요.");
        cmb_Status.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txa_Remk) == "") {
        $c.win.alert("[비고]을 입력하세요.");
        txa_Remk.focus();
        return false;
    }

    //2009.08.07 일정확정여부추가
    if (js_market == "2" && scwin.gDepCd != '3220' || js_market == "6") {
        //코스닥공시총괄팀만 해당/시장운영팀은 제외.코넥스 추가 20130522 LDJ
        if ($c.stf.getObjectValue(cmb_Confirm) == "") {
            $c.win.alert("[확정여부]를 선택하세요.");
            cmb_Confirm.focus();
            return false;
        }
    }
    //2013.09.10 SMS전송여부추가
    if (js_market == "2") {
        //코스닥 추가 20130910 LDS362
        if (scwin.gDepCd != '3220' && $c.stf.getObjectValue(cmb_SMS) == "") {
            // 코스닥 시장운영팀은 SMS 체크 제외 by LDJ_20130917
            $c.win.alert("SMS 전송여부를 선택하세요.");
            cmb_SMS.focus();
            return false;
        }
    }
    if ($c.stf.checkMaxLength(txa_Remk, 1500, "비고")) {
        return true;
    }
};
scwin.fn_Save = function() {
    if (scwin.fn_CheckForm()) {
        $c.stf.setObjectValue(txb_EMP_NO, js_emp_no);
        var res = window.confirm("[저장]하시겠습니까?");
        if (res) {
            var vCMD = ($c.stf.getObjectValue(txb_Cmd) == "C") ? "registerSchedule" : "modifySchedule";

            // 시장구분이 파생이고 등록이면 다른 메소드 사용_LSH
            if (scwin.gLdMktTp == "3" && vCMD == "registerSchedule") {
                vCMD = "registerScheduleDerivatives";
            }
            if (js_dep_cd == "11D0" && vCMD == "registerSchedule") {
                vCMD = "registerScheduleDigital";
            }
            //2009.08.07 담당자확정여부추가
            if (js_market == "2" || js_market == "6") {
                //코스닥			코넥스 추가 20130522 LDJ
                dts_Schedule.setCellData(1, "SCHDL_CONFRM_YN", $c.stf.getObjectValue(cmb_Confirm));
            }

            //2013.09.10 SMS 전송여부추가
            if (js_market == "2") {
                //코스닥 추가 20130910 LDS362
                dts_Schedule.setCellData(1, "SMS_TRNSM_YN", $c.stf.getObjectValue(cmb_SMS));

                // ********************************************************************
                // [WebSquare 전환 추가] 원본 소스와 비교 필요
                // 
                // ********************************************************************

            } /*ORG SRC: dts_Schedule.UserStatus(1) = (getObjectValue(txb_Cmd) == "C") ? TB_JOB_INSERT : TB_JOB_UPDATE;*/ X = ($c.stf.getObjectValue(txb_Cmd) == "C") ? TB_JOB_INSERT: TB_JOB_UPDATE;
            //alert(dts_Schedule.Text);
            trs_Save.Action = "/DisclosureSchedule.do?method=" + vCMD + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInput=dts_Schedule)";
            trs_Save.Post();
        }
    }
};
scwin.fn_multi = async function() {
    $c.frame.path("../../../").GWinOpen("ULDSTF30004", "/dsclmgt/ULDSTF30004.gfm", "여러일정 등록", 20, 20, 610, 540, "");
    await $c.frame.CloseFrame();
};
scwin.fn_Delete = function() {
    var res = window.confirm("[삭제]하시겠습니까?");
    if (res) {
        var vCMD = ($c.stf.getObjectValue(txb_Cmd) == "C") ? "registerSchedule" : "modifySchedule";
        //alert(vCMD);

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        $c.stf.setObjectValue(txb_EMP_NO, js_emp_no);
        $c.stf.setObjectValue(cmb_Status, "9"); /*ORG SRC: dts_Schedule.UserStatus(1) = (getObjectValue(txb_Cmd) == "C") ? TB_JOB_INSERT : TB_JOB_UPDATE;*/ X = ($c.stf.getObjectValue(txb_Cmd) == "C") ? TB_JOB_INSERT: TB_JOB_UPDATE;
        //alert(dts_Schedule.Text);
        trs_Save.Action = "/DisclosureSchedule.do?method=" + vCMD;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_Schedule)";
        trs_Save.Post();
    }
};



// 상장신청인 선택 팝업호출용
scwin.fn_SetParIsur2 = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_COM_NM.setValue(arrPar[0].ISUR_NM);
    }
};



/*
 * 상장신청인 발행기관 약명찾기(digital 사용)
 */
scwin.fn_PopFindDigitalIsurAll = async function() {
    scwin.fn_GetPar = function(arrPar) {
        arrPar[0] = "lds.stf.digital.select.isurcdall.condition";
    };
    var popTitle = "상장신청인선택";
    await $c.frame.CreateDialogFrame("ISUR_CD", "../digital/ULDSTF70017_6.gfm", popTitle, 10, 10, 410, 580, "window");
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Search_Rpt_Nm_onclick = function() {
    scwin.fn_openDiscls();
};
scwin.btn_Deadline_onclick = function() {
    popUpCalendar2(edt_Deadline);
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Save();
};
scwin.trs_Save_OnFail = function() {
    $c.stf.alert_error(trs_Save);
    dts_Schedule.Reset();
    dts_Schedule.insertRow(); // 성공일 때 Default로 한줄 추가해 놓는다.

};
scwin.trs_Save_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "저장"));
    var fr_fn_SearchMain = $c.frame.path("../").fn_SearchMain;
    var isFnSrch = $c.stf.getQuery(frame.srcUrl, "isFnSrch"); //저장완료 후 조회method 실행여부 파라미터값 저장

    /*기타시장안내서식 && 코스닥공시팀일 경우 '공시일정입력폼' 화면(STF30001)으로 이동하며
    // 이럴경우 'isFnSrch' 변수값을 파라미터로 넘겨줌
     // 해당 경우에만 첫번째 if문을 수행하며, 나머지 분기문은 기존 소스를 유지함 by LDJ_20120920 */
    if (isFnSrch == 'N') {
        await $c.frame.CloseFrame();
    } else if (fr_fn_SearchMain == undefined) {
        var parentWin = $c.frame.path("../");
        var parendID = $c.stf.getQuery(frame.srcUrl, "frameid");
        var fr_fn_Search = $c.frame.path(parendID).fn_Search;
        fr_fn_Search();
        await $c.frame.CloseFrame();
    } else {
        fr_fn_SearchMain();
        await $c.frame.CloseFrame();
    }
};
scwin.btn_Adm_Itm_Tp_Cd_onclick = function() {
    scwin.fn_Adm_Itm_Tp_Cd();
};
scwin.dts_Schedule_OnLoadCompleted = function(rowcount) {
    var vISUR_CD = dts_Schedule.getCellData(1, "ISUR_CD");
    var vLD_MKT_TP_CD = dts_Schedule.getCellData(1, "LD_MKT_TP_CD");
    if (vISUR_CD != '' && vISUR_CD.length == 5) {
        scwin.fn_ReadChrgInfo(vISUR_CD, vLD_MKT_TP_CD);
        //showObj(panel_chrg, true);

    }
};
scwin.btn_ISUR_CD_onclick = function() {
    if (js_dep_cd == "11D0") {
        //디지털증권인 경우 상장신청인 팝업호출
        scwin.fn_SetPar = fn_SetParIsur2;
        scwin.fn_PopFindDigitalIsurAll();
    } else {
        $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
    }
};
scwin.btn_VIEWDSCL_onclick = function() {
    var AcptNo = dts_Schedule.getCellData(1, "ACPT_NO");
    if (AcptNo != '') {
        $c.stf.fn_OpenDisclViewer(AcptNo, "R");
    }
};
scwin.btn_Multi_onclick = function() {
    scwin.fn_multi();
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
        scwin.fn_ReadChrgInfo2();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
    scwin.fn_ReadChrgInfo2();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    if (txb_ISUR_CD.readOnly == false) {
        Grd_com_isur.style.display = "none";
    }
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.btn_Delete_onclick = function() {
    scwin.fn_Delete();
};
scwin.txa_Remk_OnChange = function() {
    $c.stf.setObjectValue(txb_title_size, $c.stf.getStringSize($c.stf.getObjectValue(txa_Remk)));
    if ($c.stf.getStringSize($c.stf.getObjectValue(txa_Remk)) > 1500) {
        $c.stf.setObjectValue(txb_alert, '가 초과되었습니다.');
        txa_Remk.Focus();
        return;
    }
};
scwin.gform_onload = function() {
    scwin.fn_HideDebugCtrls();
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_resizeToWin();
    scwin.fn_MoveWin();
    scwin.fn_Init();
    scwin.fn_getParam();
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
};
